`,c.jsx("p",{className:"text-center text-gray-500",children:"The shift from domain architecture to zonal architecture"}),`
`,c.jsx(i.p,{children:'Zonal architecture moves away from the traditional bulky, complex "domain architecture" (where ECUs for infotainment, powertrain, etc., are grouped) to create lighter, smarter, more flexible vehicles'}),`
